# 堆优化 Dijkstra (无负权边)
def dijkstra(adj, s):
  INF = inf
  dis = [INF]*n; dis[s]=0
  pq = [(0, s)]
  while pq:
    d, u = heappop(pq)
    if d > dis[u]: continue      # 过时条目
    for v, w in adj[u]:
      if dis[v] > d + w:
        dis[v] = d + w
        heappush(pq, (dis[v], v))
  return dis
